"""Reproduction check for the enabled=False parameter feature."""
import sys
import asyncio
import tenacity
from tenacity import retry, Retrying, AsyncRetrying, RetryError

results = {"passed": 0, "failed": 0}

def test_disabled_retry_calls_once_and_propagates_exception():
    """@retry(enabled=False) calls the function once and propagates exceptions."""
    call_count = [0]

    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    def failing_func():
        call_count[0] += 1
        raise ValueError("fail")

    try:
        failing_func()
        return False, "Should have raised ValueError"
    except ValueError as e:
        if str(e) != "fail":
            return False, f"Wrong message: {e}"
        if call_count[0] != 1:
            return False, f"Expected 1 call, got {call_count[0]}"
        return True, "test_disabled_retry_calls_once_and_propagates_exception"
    except Exception as e:
        return False, f"Should have raised ValueError, got {type(e).__name__}: {e}"

def test_disabled_retry_returns_result_on_success():
    """@retry(enabled=False) returns the result on success."""
    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    def successful_func():
        return 42

    result = successful_func()
    if result != 42:
        return False, f"Expected 42, got {result}"
    return True, "test_disabled_retry_returns_result_on_success"

def test_enabled_true_default_behavior():
    """enabled=True (default) behaves as before (retries on exception)."""
    call_count = [0]

    @retry(stop=tenacity.stop_after_attempt(3))
    def failing_func():
        call_count[0] += 1
        if call_count[0] < 3:
            raise ValueError("fail")
        return "ok"

    result = failing_func()
    if result != "ok" or call_count[0] != 3:
        return False, f"Expected 'ok' with 3 calls, got {result} with {call_count[0]}"
    return True, "test_enabled_true_default_behavior"

def test_async_disabled_retry():
    """@retry(enabled=False) on async def works correctly."""
    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    async def async_failing():
        raise ValueError("async fail")

    async def run():
        try:
            await async_failing()
            return False, "Should have raised ValueError"
        except ValueError as e:
            if str(e) != "async fail":
                return False, f"Wrong message: {e}"
            return True, "test_async_disabled_retry"

    return asyncio.run(run())

def test_async_disabled_retry_success():
    """@retry(enabled=False) returns result on success for async."""
    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    async def async_success():
        return 100

    result = asyncio.run(async_success())
    if result != 100:
        return False, f"Expected 100, got {result}"
    return True, "test_async_disabled_retry_success"

def test_retry_with_disabled():
    """retry_with(enabled=False) disables retrying."""
    call_count = [0]

    @retry(stop=tenacity.stop_after_attempt(3))
    def failing_func():
        call_count[0] += 1
        raise ValueError("fail")

    # Apply retry_with(enabled=False)
    disabled_func = failing_func.retry_with(enabled=False)

    try:
        disabled_func()
        return False, "Should have raised ValueError"
    except ValueError as e:
        if str(e) != "fail":
            return False, f"Wrong message: {e}"
        if call_count[0] != 1:
            return False, f"Expected 1 call, got {call_count[0]}"
        return True, "test_retry_with_disabled"

def test_copy_with_disabled():
    """copy(enabled=False) disables retrying."""
    r = Retrying(stop=tenacity.stop_after_attempt(3))
    r_disabled = r.copy(enabled=False)

    call_count = [0]

    def failing_func():
        call_count[0] += 1
        raise ValueError("fail")

    try:
        r_disabled(failing_func)
        return False, "Should have raised ValueError"
    except ValueError:
        if call_count[0] != 1:
            return False, f"Expected 1 call, got {call_count[0]}"
        return True, "test_copy_with_disabled"

def test_wrapped_function_exposes_attributes():
    """Disabled decorated function still exposes .retry, .retry_with, .statistics."""
    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    def my_func():
        return 42

    if not hasattr(my_func, 'retry'):
        return False, "Missing .retry attribute"
    if not hasattr(my_func, 'retry_with'):
        return False, "Missing .retry_with attribute"
    if not hasattr(my_func, 'statistics'):
        return False, "Missing .statistics attribute"
    if not isinstance(my_func.retry, Retrying):
        return False, ".retry is not a Retrying instance"
    return True, "test_wrapped_function_exposes_attributes"

def test_no_retry_error_wrapping():
    """Exception should NOT be wrapped in RetryError when enabled=False."""
    call_count = [0]

    @retry(enabled=False, stop=tenacity.stop_after_attempt(3))
    def failing_func():
        call_count[0] += 1
        raise ValueError("original error")

    try:
        failing_func()
        return False, "Should have raised ValueError"
    except RetryError:
        return False, "Should NOT have raised RetryError when enabled=False"
    except ValueError:
        if call_count[0] != 1:
            return False, f"Expected 1 call, got {call_count[0]}"
        return True, "test_no_retry_error_wrapping"

# Run all tests
all_pass = True
for name in sorted(globals()):
    if name.startswith('test_'):
        func = globals()[name]
        if callable(func):
            ok, msg = func()
            if ok:
                results["passed"] += 1
                print(f"PASS: {msg}")
            else:
                results["failed"] += 1
                all_pass = False
                print(f"FAIL: {msg}")

print(f"\nResults: {results['passed']} passed, {results['failed']} failed")
sys.exit(1 if results["failed"] > 0 else 0)
